example.code:
const input = require("fs").readFileSync(0, "utf8");
const lines = input.trim().split("\n");

class Shape {
  constructor(name) {
    this.name = name;
  }

  area() {
    throw new Error("not implemented");
  }

  describe() {
    return `${this.name}: ${this.area().toFixed(2)}`;
  }
}

class Circle extends Shape {
  constructor(radius) {
    super("circle");
    this.radius = radius;
  }

  area() {
    return Math.PI * this.radius ** 2;
  }
}

class Square extends Shape {
  constructor(side) {
    super("square");
    this.side = side;
  }

  area() {
    return this.side ** 2;
  }
}

class Triangle extends Shape {
  constructor(base, height) {
    super("triangle");
    this.base = base;
    this.height = height;
  }

  area() {
    return 0.5 * this.base * this.height;
  }
}

function parseShape(line) {
  const [kind, a, b] = line.trim().split(/\s+/);
  switch (kind) {
    case "circle":
      return new Circle(Number(a));
    case "square":
      return new Square(Number(a));
    case "triangle":
      return new Triangle(Number(a), Number(b));
    default:
      throw new Error(`unknown shape: ${kind}`);
  }
}

const shapes = lines.map((line) => parseShape(line));
for (const shape of shapes) {
  console.log(shape.describe());
}
const total = shapes.reduce((sum, s) => sum + s.area(), 0);
console.log(`Total: ${total.toFixed(2)}`);
console.log(`All shapes: ${shapes.every((s) => s instanceof Shape)}`);
console.log(`Circles: ${shapes.filter((s) => s instanceof Circle).length}`);
try {
  new Shape("blob").area();
} catch (error) {
  console.log(`Shape area: ${error.message}`);
}

