const input = require("fs").readFileSync(0, "utf8");
const lines = input.trim().split("\n");

class Employee {
  constructor(name) {
    this.name = name;
  }

  monthlyPay() {
    throw new Error("not implemented");
  }
}

class Salaried extends Employee {
  constructor(name, salary) {
    super(name);
    this.salary = salary;
  }

  monthlyPay() {
    return this.salary / 12;
  }
}

class Hourly extends Employee {
  constructor(name, rate, hours) {
    super(name);
    this.rate = rate;
    this.hours = hours;
  }

  monthlyPay() {
    return this.rate * this.hours * 4;
  }
}

class Intern extends Employee {
  monthlyPay() {
    return 1000;
  }
}

function parseEmployee(line) {
  const [kind, name, a, b] = line.trim().split(/\s+/);
  switch (kind) {
    case "salaried":
      return new Salaried(name, Number(a));
    case "hourly":
      return new Hourly(name, Number(a), Number(b));
    case "intern":
      return new Intern(name);
    default:
      throw new Error(`unknown kind: ${kind}`);
  }
}

const staff = lines.map((line) => parseEmployee(line));
for (const person of staff) {
  console.log(`${person.name}: ${person.monthlyPay().toFixed(2)}`);
}
const total = staff.reduce((sum, e) => sum + e.monthlyPay(), 0);
console.log(`Total: ${total.toFixed(2)}`);
console.log(`All employees: ${staff.every((e) => e instanceof Employee)}`);
console.log(`Interns: ${staff.filter((e) => e instanceof Intern).length}`);
try {
  new Employee("Temp").monthlyPay();
} catch (error) {
  console.log(`Employee pay: ${error.message}`);
}

steps.body:
Classes are syntax over **prototypes**. `typeof Dog` is `"function"`, and every regular method you write in the class body is stored once on `Dog.prototype` (static methods live on `Dog` itself). Every instance links to that object, so all dogs share one copy of each method.

Take `class Dog extends Animal`, where `Dog` adds a `fetch()` method, and two dogs: `rex` and `max`.

```javascript harness
class Animal {
  constructor(name) {
    this.name = name;
  }
}

class Dog extends Animal {
  fetch() {
    return `${this.name} fetches.`;
  }
}

const rex = new Dog("Rex");
const max = new Dog("Max");
{{code}}
```

```javascript
console.log(Object.getPrototypeOf(rex) === Dog.prototype);              // true
console.log(Object.getPrototypeOf(Dog.prototype) === Animal.prototype); // true
console.log(rex.fetch === max.fetch);                                   // true, one shared method
```

Reading `rex.key` walks the chain: rex's own properties, then `Dog.prototype`, then `Animal.prototype`, then `Object.prototype` (where `toString` lives). The first match wins, which is how overriding works. `rex instanceof Animal` walks the same chain and is true because `Animal.prototype` is on it.

- `Object.hasOwn(obj, key)` is true only for the object's own properties, such as fields set in the constructor or declared in the class body.
- `key in obj` is true anywhere on the chain, including methods and `toString`.

Never add methods to built-in prototypes such as `Array.prototype`. Every array in the program, and every library, would see the change, and a future version of JavaScript can add a method with the same name.

example.code:
const input = require("fs").readFileSync(0, "utf8");
const names = input.trim().split(/\s+/);

class Animal {
  constructor(name) {
    this.name = name;
  }

  describe() {
    return `${this.name} is an animal.`;
  }
}

class Dog extends Animal {
  constructor(name, breed) {
    super(name);
    this.breed = breed;
  }

  fetch() {
    return `${this.name} fetches.`;
  }
}

const rex = new Dog("Rex", "collie");
const max = new Dog("Max", "pug");

console.log(`typeof Dog: ${typeof Dog}`);
console.log(`rex -> Dog.prototype: ${Object.getPrototypeOf(rex) === Dog.prototype}`);
console.log(`Dog.prototype -> Animal.prototype: ${Object.getPrototypeOf(Dog.prototype) === Animal.prototype}`);
console.log(`shared fetch: ${rex.fetch === max.fetch}`);

for (const key of names) {
  const label = Object.hasOwn(rex, key)
    ? "own"
    : key in rex
      ? "inherited"
      : "missing";
  console.log(`${key}: ${label}`);
}

