example.code:
const input = require("fs").readFileSync(0, "utf8");
const lines = input.trim().split("\n");

class ValidationError extends Error {
  constructor(field, message) {
    super(message);
    this.name = "ValidationError";
    this.field = field;
  }
}

function validateUser(user) {
  if (user.name === "-") {
    throw new ValidationError("name", "required");
  }
  if (Number.isNaN(user.age) || user.age < 0 || user.age > 150) {
    throw new ValidationError("age", "must be 0-150");
  }
}

for (const line of lines) {
  const [name, ageText] = line.trim().split(/\s+/);
  const user = { name, age: Number(ageText) };
  try {
    validateUser(user);
    console.log(`ok: ${user.name} (${user.age})`);
  } catch (error) {
    if (!(error instanceof ValidationError)) {
      throw error;
    }
    console.log(`${error.name} on ${error.field}: ${error.message}`);
  }
}

