const input = require("fs").readFileSync(0, "utf8");
const [first, ...rest] = input.trim().split("\n");
let balance = Number(first);
const amounts = rest.map(Number);

class InsufficientFundsError extends Error {
  constructor(needed, available) {
    super(`need ${needed}, have ${available}`);
    this.name = "InsufficientFundsError";
    this.needed = needed;
    this.available = available;
  }
}

function withdraw(current, amount) {
  if (amount > current) {
    throw new InsufficientFundsError(amount, current);
  }
  return current - amount;
}

for (const amount of amounts) {
  try {
    balance = withdraw(balance, amount);
    console.log(`Balance: ${balance}`);
  } catch (error) {
    if (!(error instanceof InsufficientFundsError)) {
      throw error;
    }
    console.log(`${error.name}: ${error.message} (short ${error.needed - error.available})`);
  }
}
